sed -i '/import com.example.ui.viewmodel.CyberLabViewModel/a\import androidx.compose.ui.text.input.PasswordVisualTransformation\nimport androidx.compose.material.icons.filled.Visibility\nimport androidx.compose.material.icons.filled.VisibilityOff' app/src/main/java/com/example/ui/screens/SettingsScreen.kt

sed -i '/val isMuted by viewModel.isMuted.collectAsState()/a\    val apiKey by viewModel.apiKey.collectAsState()\n    var showApiKey by remember { mutableStateOf(false) }\n    var editingApiKey by remember(apiKey) { mutableStateOf(apiKey) }\n    var isEditing by remember { mutableStateOf(false) }' app/src/main/java/com/example/ui/screens/SettingsScreen.kt

sed -i '/SettingsCard(/i\        item {\n            SettingsCard(\n                title = "Gemini API Key",\n                description = "Configure your AI Copilot API key securely. Encrypted locally using EncryptedSharedPreferences.",\n                icon = Icons.Default.VpnKey,\n                onClick = { isEditing = !isEditing },\n                actionContent = {\n                    TextButton(onClick = { isEditing = !isEditing }) {\n                        Text(if (isEditing) "CANCEL" else "EDIT", color = NeonGreen)\n                    }\n                }\n            )\n            if (isEditing) {\n                Row(modifier = Modifier.fillMaxWidth().padding(horizontal = 16.dp, vertical = 8.dp), verticalAlignment = Alignment.CenterVertically) {\n                    OutlinedTextField(\n                        value = editingApiKey,\n                        onValueChange = { editingApiKey = it },\n                        modifier = Modifier.weight(1f),\n                        placeholder = { Text("AIzaSy...") },\n                        visualTransformation = if (showApiKey) androidx.compose.ui.text.input.VisualTransformation.None else PasswordVisualTransformation(),\n                        trailingIcon = {\n                            IconButton(onClick = { showApiKey = !showApiKey }) {\n                                Icon(if (showApiKey) Icons.Default.VisibilityOff else Icons.Default.Visibility, contentDescription = null, tint = NeonGreen)\n                            }\n                        },\n                        colors = OutlinedTextFieldDefaults.colors(focusedBorderColor = NeonGreen, unfocusedBorderColor = CyberBorder, focusedTextColor = TextPrimary, unfocusedTextColor = TextPrimary, cursorColor = NeonGreen)\n                    )\n                    Spacer(modifier = Modifier.width(8.dp))\n                    Button(onClick = { viewModel.saveApiKey(editingApiKey); isEditing = false }, colors = ButtonDefaults.buttonColors(containerColor = CyberCyan)) {\n                        Text("SAVE", color = CyberBlack, fontWeight = FontWeight.Bold)\n                    }\n                }\n            }\n        }\n' app/src/main/java/com/example/ui/screens/SettingsScreen.kt

